#!/usr/bin/env python3
from pathlib import Path
import sys
from sgfmill import sgf, boards

def props(node):
    return set(node.get_raw_property_map())

def group(board, r, c):
    color = board.get(r, c)
    if color is None:
        return set(), set()
    todo=[(r,c)]; seen=set(); libs=set()
    while todo:
        p=todo.pop()
        if p in seen: continue
        seen.add(p)
        rr,cc=p
        for q in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
            qr,qc=q
            if not (0<=qr<19 and 0<=qc<19): continue
            v=board.get(qr,qc)
            if v is None: libs.add(q)
            elif v==color and q not in seen: todo.append(q)
    return seen,libs

def coord(p):
    if p is None: return '--'
    r,c=p
    return chr(c+97)+chr(18-r+97)

