from capture_solver import *
B='fa fb fc fd fe af bf cf df ef ff'.split()
W='aa ba ca ab bb cb db ac bc cc ad bd cd ae be ce de ee'.split()
R='da ea eb dc ec dd ed'.split()
st=setup(B,W); dom=[idx(*p(z)) for z in R]; target=[idx(*p(z)) for z in W]
d,m,rec=solve(st,target,BLACK,dom,13)
print('root',d,m)

def md(cur,turn,prev,maxd=13):
 for d in range(maxd+1):
  ok,_=rec(cur,turn,d,prev)
  if ok:return d
 return None

def moves(cur,turn,prev):
 out=[]
 for i in dom:
  ns=play(cur,i,turn,prev)
  if ns is not None: out.append((i,ns))
 if turn==WHITE:out.append((-1,cur))
 return out

def line(cur,turn,prev,n=0):
 if not any(cur[i]==WHITE for i in target):return []
 opts=[]
 for i,ns in moves(cur,turn,prev):opts.append((md(ns,3-turn,cur),i,ns))
 if turn==BLACK:
  opts=[x for x in opts if x[0] is not None];opts.sort(key=lambda x:x[0])
 else:
  opts.sort(key=lambda x:99 if x[0] is None else -x[0])
 if not opts:return []
 dist,i,ns=opts[0]
 return [(('B' if turn==1 else 'W'), 'pass' if i<0 else sxy(i%N,i//N),dist)]+line(ns,3-turn,cur,n+1)

# after root correct
ri=idx(*p('eb'));s1=play(st,ri,BLACK,None)
for i,ns in moves(s1,WHITE,st):
 z='pass' if i<0 else sxy(i%N,i//N)
 print('W response',z,'then capture depth',md(ns,BLACK,s1),'pv',line(ns,BLACK,s1))
print('wrong first moves and defender replies')
for bi,bstate in moves(st,BLACK,None):
 z=sxy(bi%N,bi//N)
 if z=='eb':continue
 replies=[]
 for wi,wstate in moves(bstate,WHITE,st):
  dep=md(wstate,BLACK,bstate)
  if dep is None: replies.append('pass' if wi<0 else sxy(wi%N,wi//N))
 print(z,replies)
